import time


class RateLimiter:
    def __init__(self, per_second):
        self.per_second = per_second
        self.last = 0.0

    def allow(self):
        now = time.monotonic()
        if now - self.last >= 1 / self.per_second:
            self.last = now
            return True
        return False
